action.command:
cat > /tmp/findstr.js <<'EOF'
const fs=require("fs");
const path=require("path");
function dumpStrings(buf){
  let out="";
  for(let i=0;i<buf.length;i++){const c=buf[i]; if(c>=32&&c<127) out+=String.fromCharCode(c); else out+="\n";}
  return out.split("\n").filter(s=>s.length>=4);
}
const root="/tmp/logic-extract";
const re=new RegExp("maven.pkg|packages.github|swcode.*github|githubPackages|setUrl|amazonaws|releases|credentials|http","i");
function walk(d){
  for(const e of fs.readdirSync(d,{withFileTypes:true})){
    const p=path.join(d,e.name);
    if(e.isDirectory()) walk(p);
    else if(e.name.endsWith(".class")){
      const strs=dumpStrings(fs.readFileSync(p));
      const hits=strs.filter(s=>re.test(s));
      if(hits.length){
        console.log("== "+p.replace(root,""));
        hits.slice(0,25).forEach(h=>console.log("    "+h));
      }
    }
  }
}
walk(root);
EOF
node /tmp/findstr.js 2>&1 | head -80

